const listInboxMessagesFiltered = `-- name: ListInboxMessagesFiltered :many
SELECT
    im.id, im.project_inbox_id, im.message_id, im.imap_uid, im.thread_id, im.in_reply_to, im."references", im.subject, im.from_email, im.from_name, im.to_emails, im.cc_emails, im.bcc_emails, im.reply_to, im.body_text, im.body_html, im.text_signature, im.html_signature, im.snippet, im.headers, im.raw_size, im.has_attachments, im.importance, im.converted, im.status, im.is_spam, im.spam_score, im.converted_at, im.converted_by, im.email_date, im.received_at, im.processed_at, im.created_at, im.updated_at,
    t.id AS task_id, t.title AS task_title, t.task_number AS task_number,
    ts.name AS task_status_name, ts.color AS task_status_color,
    u.id AS conv_user_id, u.first_name AS conv_user_first_name, u.last_name AS conv_user_last_name
FROM "inbox_messages" im
LEFT JOIN "tasks" t ON t.inbox_message_id = im.id
LEFT JOIN "task_statuses" ts ON t.status_id = ts.id
LEFT JOIN "users" u ON im.converted_by = u.id
WHERE im.project_inbox_id = $1::uuid
  AND ($2::"MessageStatus" IS NULL OR im.status = $2::"MessageStatus")
  AND ($3::boolean = true OR im.is_spam = false)
  AND ($4::text IS NULL OR im.from_email ILIKE '%' || $4::text || '%' ESCAPE '\')
  AND ($5::timestamp IS NULL OR im.email_date >= $5::timestamp)
  AND ($6::timestamp IS NULL OR im.email_date <= $6::timestamp)
  AND ($7::text IS NULL OR (
      im.subject ILIKE '%' || $7::text || '%' ESCAPE '\'
      OR COALESCE(im.body_text, '') ILIKE '%' || $7::text || '%' ESCAPE '\'
  ))
ORDER BY im.email_date DESC
`

